-- public.order_fits(p_world uuid, p_uid uuid, p_def text, p_ql integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.order_fits(p_world uuid, p_uid uuid, p_def text, p_ql integer)
 RETURNS SETOF item
 LANGUAGE sql
 STABLE
AS $function$
  select i.* from item i
   where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
     and i.def = p_def and i.ql >= p_ql and not i.locked and not i.issued and i.deal is null and i.creature is null
     and not exists (select 1 from item c where c.inside = i.id)
     and not exists (select 1 from player pl cross join jsonb_each_text(pl.equipped) e
                      where pl.world_id = p_world and pl.uid = p_uid and e.value = i.id::text)
$function$
